  FT["PH-H7376"] = {"id":"PH-H7376","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2000/ra_8908_2000.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Magsaysay市","en":"An Act Establishing a Secondary School in Barangay Lower Bala, Municipality of Magsaysay, Province of Davao Del Sur to Be Known as the Lower Bala National High School and Appropriating Funds Therefor","orig":"An Act Establishing a Secondary School in Barangay Lower Bala, Municipality of Magsaysay, Province of Davao Del Sur to Be Known as the Lower Bala National High School and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 8908","issuingBody":"Congress of the Philippines","promulgatedDate":"2000-08-22","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2000/ra_8908_2000.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H7376-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"A secondary school in Barangay Lower Bala, Municipality of Magsaysay, Province of Davao del Sur shall be established under the direct supervision of the Department of Education, Culture and Sports to be known as the Lower Bala National High School."}},{"id":"PH-H7376-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H7376-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p105"};
