  FT["PH-H7380"] = {"id":"PH-H7380","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2000/ra_8912_2000.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Sultan Gumander市","en":"An Act Creating a National High School in the Municipality of Sultan Gumander, Province of Lanao Del Sur to Be Known as the Sultan Gumander National High School and Appropriating Funds Therefor","orig":"An Act Creating a National High School in the Municipality of Sultan Gumander, Province of Lanao Del Sur to Be Known as the Sultan Gumander National High School and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 8912","issuingBody":"Congress of the Philippines","promulgatedDate":"2000-08-22","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2000/ra_8912_2000.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H7380-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision and control of the Department of Education, Culture and Sports, the Sultan Gumander National High School in the Municipality of Sultan Gumander, Province of Lanao del Sur."}},{"id":"PH-H7380-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary for the initial implementation of this Act shall be charged against the current year's appropriations of the Department of Education, Culture and Sports - Autonomous Regional Government in Muslim Mindanao (ARMM). Thereafter, such sums as may be necessary for the continuous operation and maintenance of the Sultan Gumander National High School shall be included in the annual General Appropriations Act."}},{"id":"PH-H7380-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p105"};
  FT["PH-H7381"] = {"id":"PH-H7381","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2000/ra_8913_2000.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Separating the Marawi City National High School - Angoyao National High School Annex in the City of Marawi, Province of Lanao Del Sur From the Marawi City National High School and Converting the Same Into An Independent National High School to Be Known as the Angoyao National High School and Appropriating Funds Therefor","orig":"An Act Separating the Marawi City National High School - Angoyao National High School Annex in the City of Marawi, Province of Lanao Del Sur From the Marawi City National High School and Converting the Same Into An Independent National High School to Be Known as the Angoyao National High School and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 8913","issuingBody":"Congress of the Philippines","promulgatedDate":"2000-08-22","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2000/ra_8913_2000.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H7381-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Marawi City National High School - Angoyao National High School Annex in the City of Marawi, Province of Lanao del Sur is hereby separated from the Marawi City National High School and converted into an independent national high school to be known as the Angoyao National High School."}},{"id":"PH-H7381-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Department of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H7381-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All personnel, records, assets and liabilities of the Marawi City National High School - Angoyao National High School Annex are hereby transferred to and absorbed by the Angoyao National High School."}},{"id":"PH-H7381-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The amount necessary to carry out the initial implementation of this Act shall be charged against the current year's appropriations of the Marawi City National High School - Angoyao National High School Annex. Thereafter, such amount as may be necessary for the continued operation and maintenance of the Angoyao National High School shall be included in the annual General Appropriations Act."}},{"id":"PH-H7381-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p105"};
  FT["PH-H7382"] = {"id":"PH-H7382","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2000/ra_8914_2000.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Malaybalay市","en":"An Act Converting the San Martin Barangay High School in Barangay San Martin, City of Malaybalay, Province of Bukidnon Into a National Agro-Industrial High School to Be Known as the San Martin National Agroindustrial High School and Appropriating Funds Therefor","orig":"An Act Converting the San Martin Barangay High School in Barangay San Martin, City of Malaybalay, Province of Bukidnon Into a National Agro-Industrial High School to Be Known as the San Martin National Agroindustrial High School and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 8914","issuingBody":"Congress of the Philippines","promulgatedDate":"2000-08-22","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2000/ra_8914_2000.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H7382-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The San Martin Barangay High School in Barangay San Martin, City of Malaybalay, Province of Bukidnon is hereby converted into a national agro-industrial high school to be known as the San Martin Agro-Industrial National High School. The said school shall be under the supervision of the Department of Education, Culture and Sports."}},{"id":"PH-H7382-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H7382-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p105"};
  FT["PH-H7383"] = {"id":"PH-H7383","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2000/ra_8915_2000.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Maramag市","en":"An Act Establishing a National High School in Barangay Kuya, Municipality of Maramag, Province of Bukidnon, to Be Known as the Kuya National High School","orig":"An Act Establishing a National High School in Barangay Kuya, Municipality of Maramag, Province of Bukidnon, to Be Known as the Kuya National High School"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 8915","issuingBody":"Congress of the Philippines","promulgatedDate":"2000-08-22","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2000/ra_8915_2000.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H7383-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby established, under the supervision of the Department of Education, Culture and Sports, a national high school in Barangay Kuya, Municipality of Maramag, Province of Bukidnon, to be known as the Kuya National High School."}},{"id":"PH-H7383-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Education, Culture and Sports shall issue the necessary rules and regulations for the effective implementation of this Act."}},{"id":"PH-H7383-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H7383-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p105"};
  FT["PH-H7384"] = {"id":"PH-H7384","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2000/ra_8916_2000.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"设立Bacuag市","en":"An Act Converting the Bacuag Annex of the Gigaquit National School of Home Industries in the Municipality of Bacuag, Province of Surigao Del Norte Into a National Vocational Agro-Industrial School and Appropriating Funds Therefor","orig":"An Act Converting the Bacuag Annex of the Gigaquit National School of Home Industries in the Municipality of Bacuag, Province of Surigao Del Norte Into a National Vocational Agro-Industrial School and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 8916","issuingBody":"Congress of the Philippines","promulgatedDate":"2000-08-22","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2000/ra_8916_2000.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H7384-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Bacuag Annex of the Gigaquit National School of Home Industries in the Municipality of Bacuag, Province of Surigao del Norte is converted into a national vocational school to be known as the Bacuag National Agro-Industrial School."}},{"id":"PH-H7384-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In addition to the vocational secondary curriculum, the Bacuag National Agro-Industrial School shall offer short-term agricultural and industrial courses and non-formal education classes relevant to its environment. The school shall not charge tuition fees for enrollment in the vocational secondary curriculum, short-term agricultural and industrial courses and non-formal education classes."}},{"id":"PH-H7384-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Department of Education, Culture and Sports (DECS) shall promulgate the rules and regulations to implement the provisions of this Act in time for the opening of the next school term following its approval."}},{"id":"PH-H7384-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The amount necessary to implement the provisions of this Act shall be charged against the current year's appropriations of the Gigaquit National School of Home Industries -Bacuag Annex. Thereafter, such sums as may be necessary for the operations and maintenance of the Bacuag National Agro-Industrial School shall be included in the annual General Appropriations Act."}},{"id":"PH-H7384-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p105"};
  FT["PH-H7385"] = {"id":"PH-H7385","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2000/ra_8917_2000.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Libjo市","en":"An Act Establishing a Regular National High School in Barangay Plaridel, Municipality of Libjo, Province of Surigao Del Norte to Be Known as the Plaridel National High School and Appropriating Funds Therefor","orig":"An Act Establishing a Regular National High School in Barangay Plaridel, Municipality of Libjo, Province of Surigao Del Norte to Be Known as the Plaridel National High School and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 8917","issuingBody":"Congress of the Philippines","promulgatedDate":"2000-08-22","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2000/ra_8917_2000.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H7385-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Department of Education, Culture and Sports, a national high school in Barangay Plaridel, Municipality of Libjo, Province of Surigao del Norte to be known as the Plaridel National High School."}},{"id":"PH-H7385-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H7385-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p105"};
  FT["PH-H7386"] = {"id":"PH-H7386","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2000/ra_8918_2000.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Separating the Ligayan National High School Extension in Sitangkai, Municipality of Sitangkai, Province of Tawi-Tawi, From the Ligayan National High School and Converting the Same Into An Independent National High School to Be Known as the Sitangkai National High School and Providing Funds Therefor","orig":"An Act Separating the Ligayan National High School Extension in Sitangkai, Municipality of Sitangkai, Province of Tawi-Tawi, From the Ligayan National High School and Converting the Same Into An Independent National High School to Be Known as the Sitangkai National High School and Providing Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 8918","issuingBody":"Congress of the Philippines","promulgatedDate":"2000-08-22","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2000/ra_8918_2000.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H7386-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Ligayan National High School Extension in Sitangkai, Municipality of Sitangkai, Province of Tawi- Tawi is hereby separated from the Ligayan National High School and converted into an independent national high school to be known as the Sitangkai National High School."}},{"id":"PH-H7386-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Department of Education, Culture and Sports - Autonomous Regional Government in Muslim Mindanao (ARMM) shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H7386-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All personnel, records, assets and liabilities of the Ligayan National High School Extension are hereby transferred to and absorbed by the Sitangkai National High School."}},{"id":"PH-H7386-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The amount necessary for the initial implementation of this Act shall be charged against the current year's appropriations of the Ligayan National High School Extension in Sitangkai under the Department of Education, Culture and Sports -Autonomous Regional Government in Muslim Mindanao (ARMM). Thereafter, such sums as may be necessary for the continuous operation and maintenance of the Sitangkai National High School shall be included in the annual General Appropriations Act."}},{"id":"PH-H7386-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p105"};
  FT["PH-H7387"] = {"id":"PH-H7387","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2000/ra_8919_2000.html","fetchedAt":"2026-10-06","articleCount":7,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Separating the Ditoray National High School Annex in Barangay Lison Valley, City of Pagadian, Province of Zamboanga Del Sur From the Ditoray National High School, Also in the City of Pagadian, Province of Zamboanga Del Sur and Converting It Into An Independent National High School to Be Known as the Lison Valley National High School, and Appropriating Funds Therefor","orig":"An Act Separating the Ditoray National High School Annex in Barangay Lison Valley, City of Pagadian, Province of Zamboanga Del Sur From the Ditoray National High School, Also in the City of Pagadian, Province of Zamboanga Del Sur and Converting It Into An Independent National High School to Be Known as the Lison Valley National High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 8919","issuingBody":"Congress of the Philippines","promulgatedDate":"2000-08-22","completenessNote":"全文，共 7 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2000/ra_8919_2000.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H7387-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Ditoray National High School Annex in Barangay Lison Valley, Pagadian City, Province of Zamboanga del Sur shall be separated from the Ditoray National High School in Pagadian City, Province of Zamboanga del Sur and shall be converted into an independent national high school to be known as the Lison Valley National High School."}},{"id":"PH-H7387-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Department of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the provisions of this Act."}},{"id":"PH-H7387-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Lison Valley High School shall be headed by a principal to be appointed by the Secretary of Education, Culture and Sports. The incumbent teacher-in-charge of the Ditoray National High School Annex shall continue as such until his successor shall have been appointed and qualified."}},{"id":"PH-H7387-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"All the assets, fixed and movable, personnel and records of the Ditoray National High School Annex are hereby transferred to the Lison Valley National High School: Provided, however, That the positions, rights and security of tenure of personnel therein employed under existing laws prior to separation from the mother school are not impaired."}},{"id":"PH-H7387-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"All parcels of land belonging to the government occupied by the Ditoray National High School Annex in Barangay Lison Valley are hereby declared to be the property of the Lison Valley National High School and shall be titled under that name: Provided, That should the Lison Valley National High School cease to exist or is abolished or such parcel of land is no longer needed by the Lison Valley National High School, the same shall revert to the Province of Zamboanga del Sur."}},{"id":"PH-H7387-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The amount necessary for the initial implementation of this Act shall be charged against the current year's appropriation of the Ditoray National High School - Barangay Lison Valley Annex. Thereafter, such sums as may be necessary for the continuous operation and maintenance of the Lison Valley National High School shall be included in the annual General Appropriations Act."}},{"id":"PH-H7387-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p105"};
  FT["PH-H7388"] = {"id":"PH-H7388","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2000/ra_8920_2000.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Nabunturan市","en":"An Act Converting the Bayabas Barangay High School of Barangay Bayabas, Municipality of Nabunturan, Compostela Valley Province Into a National High School to Be Known as the Bayabas National High School and Appropriating Funds Therefor","orig":"An Act Converting the Bayabas Barangay High School of Barangay Bayabas, Municipality of Nabunturan, Compostela Valley Province Into a National High School to Be Known as the Bayabas National High School and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 8920","issuingBody":"Congress of the Philippines","promulgatedDate":"2000-08-22","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2000/ra_8920_2000.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H7388-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Bayabas Barangay High School of Barangay Bayabas, Municipality of Nabunturan, Compostela Valley Province is hereby converted into a national high school to be known as the Bayabas National High School."}},{"id":"PH-H7388-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H7388-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p105"};
  FT["PH-H7389"] = {"id":"PH-H7389","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2000/ra_8921_2000.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Pantukan市","en":"An Act Converting the Tambongon Barangay High School of Barangay Tambongon, Municipality of Pantukan, Compostela Valley Province Into a National High School to Be Known as the Tambongon National High School and Providing Appropriate Funds Therefor","orig":"An Act Converting the Tambongon Barangay High School of Barangay Tambongon, Municipality of Pantukan, Compostela Valley Province Into a National High School to Be Known as the Tambongon National High School and Providing Appropriate Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 8921","issuingBody":"Congress of the Philippines","promulgatedDate":"2000-08-22","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2000/ra_8921_2000.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H7389-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Tambongon Barangay High School of Barangay Tambongon, Municipality of Pantukan, Compostela Valley Province is hereby converted into a national high school to be known as the Tambongon National High School."}},{"id":"PH-H7389-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Department of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H7389-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H7389-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p105"};
  FT["PH-H7390"] = {"id":"PH-H7390","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2000/ra_8922_2000.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Converting the Paloc Barangay High School in Barangay Paloc, Maragusan, Compostela Valley Province Into the Paloc National High School, Providing Funds Therefor and for Other Purposes","orig":"An Act Converting the Paloc Barangay High School in Barangay Paloc, Maragusan, Compostela Valley Province Into the Paloc National High School, Providing Funds Therefor and for Other Purposes"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 8922","issuingBody":"Congress of the Philippines","promulgatedDate":"2000-08-22","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2000/ra_8922_2000.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H7390-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Paloc Barangay High School in Barangay Paloc, Municipality of Maragusan, Compostela Valley Province is hereby nationalized to be known as the Paloc National High School."}},{"id":"PH-H7390-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"All personnel, records, equipment, buildings, facilities and other properties of the Paloc Barangay High School are hereby transferred to the Paloc National High School."}},{"id":"PH-H7390-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H7390-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p105"};
